import json

def extract_config(config_file_path):
    # Open the config file in read mode
    with open(config_file_path, ""r"") as f:
        # Load the JSON content of the file into a Python dictionary using the json library
        config = json.load(f)

    # Create a tailored dictionary-based data structure to store the configuration information
    config_dict = {}

    # Iterate over the keys in the JSON object and extract the configuration values
    for key, value in config.items():
        if key == ""server"":
            config_dict[""server""] = value[""url""]
        elif key == ""database"":
            config_dict[""database""] = value[""name""]
        else:
            config_dict[key] = value

    return config_dict
