        self.height = height

class Forest:
    def __init__(self, start_x, end_x):
        self.start_x = start_x
        self.end_x = end_x
        self.treeRegistry = {}

    def addFactoryFunction(self, factoryID, factoryFunction):
        self.treeRegistry[factoryID] = factoryFunction

    def createTreeInstance(self, factoryID):
        if factoryID not in self.treeRegistry:
            raise ValueError(""Invalid factory ID"")
        return self.treeRegistry[factoryID](start_x=self.start_x, end_x=self.end_x)

    def jsonify(self):
        trees = [tree.toJSON() for tree in self]
        return json.dumps(trees)
```
