The goal is to demonstrate how to encapsulate data and behavior in objects, utilize inheritance for different animal types, manage object collections, and output data in a standardized format like JSON.",680,,"['```
import json

class Animal:
    def __init__(self, species, age, gender):
        self.species = species
        self.age = age
        self.gender = gender

    def set_attributes(self, species, age, gender):
        self.species = species
        self.age = age
        self.gender = gender

    def get_attributes(self):
        return {
            ""species"": self.species,
            ""age"": self.age,
            ""gender"": self.gender
        }

class Zoo:
    def __init__(self):
        self.animals = {}
        self.next_id = 0

    def add_animal(self, animal):
        self.animals[f""animal_{self.next_id}""] = animal
        self.next_id += 1

    def remove_animal(self, animal):
        del self.animals[f""animal_{self.next_id}""]

    def display_animals(self):
        for key in self.animals:
            print(key)

    def register_factory_method(self, id, species, age, gender):
        self.factory_methods[id] = {
            ""species"": species,
            ""age"": age,
            ""gender"": gender
        }

    def create_animal(self, id):
        return Animal(
            self.factory_methods[id][""species""],
            self.factory_methods[id][""age""],
            self.factory_methods[id][""gender""]
        )

    def to_json(self):
        return json.dumps([animal.get_attributes() for animal in self.animals])
```
