# Display animals
zoo.display_animals()

# Register a factory method
zoo.register_factory_method(""tiger"", ""Tiger"", 2, ""Female"")

# Create an animal using the factory method
tiger = zoo.create_animal(""tiger"")

# Convert animals to JSON
print(zoo.to_json())
