import java
from java.security import NoSuchAlgorithmException
from java.security import MessageDigest

class HashCalculator(object):
    @staticmethod
    def calculateMD5(input):
        try:
            md = MessageDigest.getInstance(""MD5"")
            hash = md.digest(input.encode())
            return toHexString(hash)
        except NoSuchAlgorithmException as e:
            print(""Error while calculating MD5 hash:"", e)
            return None

    @staticmethod
    def calculateMD5(file_path):
        try:
            md = MessageDigest.getInstance(""MD5"")
            with open(file_path, ""rb"") as f:
                data = f.read()
            hash = md.digest(data)
            return toHexString(hash)
