# Python code for managing animals and their data
from abc import ABC, abstractmethod
import json

class Animal:
    def __init__(self, species, age, gender):
        self.species = species
        self.age = age
        self.gender = gender

    @abstractmethod
    def set_species(self, species):
        pass

    @abstractmethod
    def get_species(self):
        pass

    @abstractmethod
    def set_age(self, age):
        pass

    @abstractmethod
    def get_age(self):
        pass

    @abstractmethod
    def set_gender(self, gender):
        pass

    @abstractmethod
    def get_gender(self):
        pass

class Mammal(Animal):
    def __init__(self, species, age, gender, fur_color):
        super().__init__(species, age, gender)
        self.fur_color = fur_color

    def set_fur_color(self, fur_color):
        self.fur_color = fur_color

    def get_fur_color(self):
        return self.fur_color

class Reptile(Animal):
    def __init__(self, species, age, gender, scales_count):
        super().__init__(species, age, gender)
        self.scales_count = scales_count

    def set_scales_count(self, scales_count):
        self.scales_count = scales_count

    def get_scales_count(self):
        return self.scales_count

class Bird(Animal):
    def __init__(self, species, age, gender, wingspan):
        super().__init__(species, age, gender)
        self.wingspan = wingspan

    def set_wingspan(self, wingspan):
        self.wingspan = wingspan

    def get_wingspan(self):
        return self.wingspan

class Zoo:
    def __init__(self):
        self.animals = []

    def add_animal(self, animal):
        self.animals.append(animal)

    def get_all_animals(self):
        return self.animals

    def convert_to_json(self):
        json_string = json.dumps(self.get_all_animals(), indent=4)
        return json_string

