def manage_inventory(request: dict) -> str:
    product_id = request.get(""product_id"")
    quantity = request.get(""quantity"")
    action = request.get(""action"")

    if not product_id or not quantity or not action:
        return ""Invalid input""

    # validate product existence and stock level
    if not validate_product(product_id):
        return ""Product does not exist""
    elif not validate_stock(product_id, quantity):
        return ""Insufficient stock""

    # update inventory records
    if action == ""add"":
        add_to_inventory(product_id, quantity)
    elif action == ""remove"":
        remove_from_inventory(product_id, quantity)

    # retrieve product information based on ID
    product = get_product_by_id(product_id)

    return f""Product {product['name']} updated successfully""

def validate_product(product_id: int) -> bool:
    product = get_product_by_id(product_id)
    if not product:
        return False
    else:
        return True

def validate_stock(product_id: int, quantity: int) -> bool:
    product = get_product_by_id(product_id)
    if product[""quantity""] < quantity:
        return False
    else:
        return True

def add_to_inventory(product_id: int, quantity: int):
    product = get_product_by_id(product_id)
    product[""quantity""] += quantity
    save_inventory_records(product)

def remove_from_inventory(product_id: int, quantity: int):
    product = get_product_by_id(product_id)
    product[""quantity""] -= quantity
    save_inventory_records(product)

def get_product_by_id(product_id: int) -> dict:
    return {""name"": ""Product X"", ""quantity"": 10}

def save_inventory_records(product: dict):
