class EmployeeManager:
    def __init__(self):
        self.employees = {}
        self.departments = {}

    def initialize_data(self):
        self.current_timestamp = datetime.now()
        self.next_id = 0

    def generate_employee_record(self, department):
        employee = {
            ""id"": f""{self.departments[department]}#{self.next_id}"",
            ""department"": department,
            ""status"": ""active""
        }
        self.employees[employee[""id""]] = employee
        self.next_id += 1
        return employee

    def assign_status(self, employee_id, status):
        if employee_id in self.employees:
            self.employees[employee_id][""status""] = status
        else:
            raise ValueError(""Invalid employee ID"")

    def update_status(self, employee_id, new_status):
        if employee_id in self.employees:
            self.employees[employee_id][""status""] = new_status
        else:
            raise ValueError(""Invalid employee ID"")

    def save_records(self, filepath):
        with open(filepath, ""w"") as f:
            json.dump(self.employees, f)

    def load_records(self, filepath):
        with open(filepath, ""r"") as f:
            self.employees = json.load(f)
