import os

def count_files_in_directory(input_directory, output_file=None):
    total_files = 0

    for root, dirs, files in os.walk(input_directory):
        total_files += len(files)

    if output_file:
        with open(output_file, 'w') as f:
            f.write(f""Total files: {total_files}"")
    else:
        print(f""Total files: {total_files}"")

def main():
    parser = argparse.ArgumentParser(description=""Count files in a directory and its subdirectories."")

    parser.add_argument('-d', '--directory', type=str, required=True,
                        help=""Input directory path."")

    parser.add_argument('-o', '--output', type=str, default=None,
                        help=""Output file path to store the result."")

    args = parser.parse_args()

    if args.output:
        if not args.output.endswith('.txt'):
            print(""Output file should be a .txt file."")
            return

        with open(args.output, 'w') as f:
            f.write(""Processing...\n"")

    try:
        count_files_in_directory(args.directory, args.output)

        if args.output:
            with open(args.output, 'a') as f:
                f.write(""\nProcessing complete."")

    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()']",0,[0],[],True,0,0,0,

Next, develop another function that filters through these logs based on specific criteria such as user age, recent transactions within a minute, popularity (measured by average actions per log), and calculates weighted sums for each log. This function should return the highest weighted sum along with its corresponding transaction ID. If no suitable log is found or if the input list is empty, it should return None for both values.",680,,"['```
import datetime
from typing import List, Dict, Union

def generate_user_activity_logs(num_logs: int) -> List[Dict[str, Union[int, float]]]:
    """"""
    Generates an array of unique user activity logs. Each log includes the current timestamp, device type (mobile, desktop, or tablet), time spent on the app (in seconds), and number of actions performed. The time spent on the app and number of actions vary based on the device type.

    :param num_logs: Number of logs to generate
    :return: Array of unique user activity logs
    """"""
    logs = []
    for i in range(num_logs):
        log = {}
        now = datetime.datetime.now()
        device_type = random.choice(['mobile', 'desktop', 'tablet'])
        time_spent = random.randint(1, 60) if device_type == 'mobile' else random.randint(20, 120)
        actions = random.randint(5, 20) if device_type == 'desktop' else random.randint(10, 30)
        log['timestamp'] = now.isoformat()
        log['device'] = device_type
        log['time_spent'] = time_spent
        log['actions'] = actions
        logs.append(log)
    return logs

def filter_user_activity_logs(logs: List[Dict[str, Union[int, float]]], criteria: Dict[str, int]) -> List[Dict[str, Union[int, float]]]:
    """"""
    Filters through the user activity logs based on specific criteria. The criteria can include user age, recent transactions within a minute, popularity (measured by average actions per log), and calculates weighted sums for each log. Returns the highest weighted sum along with its corresponding transaction ID. If no suitable log is found or if the input list is empty, it should return None for both values.

    :param logs: List of user activity logs
    :param criteria: Dictionary of filter criteria (age, recent transactions within a minute, popularity)
    :return: Highest weighted sum and corresponding transaction ID, or None if no suitable log is found
    """"""
    filtered_logs = []
    for log in logs:
        for k, v in criteria.items():
            if k == 'age':
                if log['age'] >= v:
                    filtered_logs.append(log)
            elif k == 'recent_transactions':
                if log['timestamp'] > datetime.datetime.now() - datetime.timedelta(minutes=v):
                    filtered_logs.append(log)
            elif k == 'popularity':
                average = sum(log['actions']) / len(log['actions'])
                if average >= v:
                    filtered_logs.append(log)
    weighted_sums = []
    for log in filtered_logs:
        weighted_sum = 0
        for k, v in log.items():
            if k == 'timestamp' or k == 'device':
                continue
            else:
                weighted_sum += v * (1 + len(filtered_logs))
        weighted_sums.append(weighted_sum)
    highest_weighted_sum = max(weighted_sums)
    corresponding_transaction_id = filtered_logs[weighted_sums.index(highest_weighted_sum)]['transaction_id']
    if len(filtered_logs) == 0 or highest_weighted_sum is None:
        return None, None
    else:
        return highest_weighted_sum, corresponding_transaction_id
