0,"Create a class-based movie theater ticketing system. Implement a class for different ticket types (regular, VIP, student) with attributes like price, seat number, and showtime. Include methods to add tickets, update their status (reserved, purchased), and retrieve all tickets' information. Add exception handling for invalid seat numbers or sold-out showtimes. Develop a user interface for theater staff to interact with the system and perform operations.",680,,"['Here is the code block for the movie theater ticketing system:
```
# Class for different ticket types (regular, VIP, student)
class TicketType:
    def __init__(self, price, seat_number, showtime):
        self.price = price
        self.seat_number = seat_number
        self.showtime = showtime

    # Add a ticket to the system
    def add_ticket(self, ticket_type, seat_number, showtime):
        try:
            if seat_number in range(1, 50) and showtime in range(1, 10):
                self.ticket_types[ticket_type].append({""price"": price, ""seat_number"": seat_number, ""showtime"": showtime})
        except Exception as e:
            print(""Invalid seat number or sold-out showtime"")

    # Update the status of a ticket (reserved or purchased)
    def update_ticket(self, ticket_type, seat_number, new_status):
        try:
            if new_status == ""reserved"" or new_status == ""purchased"":
                self.ticket_types[ticket_type][seat_number][""status""] = new_status
        except Exception as e:
            print(""Invalid status"")

    # Retrieve all tickets' information
    def get_all_tickets(self):
        return self.ticket_types
