[PYTHON]
import json
from abc import ABC, abstractmethod

class Animal(ABC):
    def __init__(self, species, age, gender):
        self.species = species
        self.age = age
        self.gender = gender

    @abstractmethod
    def get_details(self):
        pass

class Zoo:
    def __init__(self):
        self.animal_registry = {}
        self.animals = []

    def register_animal(self, animal_id, animal_class):
        if animal_id not in self.animal_registry:
            self.animal_registry[animal_id] = animal_class

    def create_animal(self, animal_id):
        if animal_id in self.animal_registry:
            AnimalClass = self.animal_registry[animal_id]
            return AnimalClass()
        else:
            raise ValueError(""Animal ID not found in registry"")

    def add_animal(self, animal):
        if isinstance(animal, Animal) and animal not in self.animals:
            self.animals.append(animal)
            print(f""Added {animal.species} to the zoo."")
        else:
            raise TypeError(""Invalid animal type"")

    def remove_animal(self, species=None):
        for i, animal in enumerate(self.animals):
            if (species is None or species == animal.species) and isinstance(animal, Animal):
                del self.animals[i]
                print(f""Removed {animal.species} from the zoo."")
                break

    def display_animals(self):
        for animal in self.animals:
            print(animal.get_details())

class Mammal(Animal):    
    def get_details(self):
        return f""{self.species} - Age: {self.age}, Gender: {self.gender}""

class Bird(Animal):    
    def get_details(self):
