```
import json
from abc import ABC, abstractmethod

class Animal(ABC):
    def __init__(self, species, age, gender):
        self.species = species
        self.age = age
        self.gender = gender

    @abstractmethod
    def get_details(self):
        pass

class Zoo:
    def __init__(self):
        self.animal_registry = {}
        self.animals = []

    def register_animal(self, animal_id, animal_class):
        self.animal_registry[animal_id] = animal_class

    def create_animal(self, animal_id):
        if animal_id in self.animal_registry:
            AnimalClass = self.animal_registry[animal_id]
            return AnimalClass()
        else:
            raise ValueError(""Animal ID not found in registry"")

    def add_animal(self, animal):
        if isinstance(animal, Animal) and animal not in self.animals:
            self.animals.append(animal)
            print(f""Added {animal.species} to the zoo."")
        else:
            raise TypeError(""Invalid animal type"")

    def remove_animal(self, species=None):
        for i, animal in enumerate(self.animals):
            if (species is None or species == animal.species) and isinstance(animal, Animal):
                del self.animals[i]
                print(f""Removed {animal.species} from the zoo."")
                break

    def display_animals(self):
        for animal in self.animals:
            print(animal.get_details())

def convert_to_json(zoo_obj):
    animals_list = [animal.get_details() for animal in zoo_obj.animals]
    json_string = json.dumps(animals_list)
    return json_string

# Create a Zoo instance
zoo = Zoo()

# Register new types of animals with unique IDs
zoo.register_animal('001', Mammal)
zoo.register_animal('002', Bird)

# Create instances of registered animals and add them to the zoo
zebra_instance = zoo.create_animal('001')
lion_instance = zoo.create_animal('001')
eagle_instance = zoo.create_animal('002')

# Add the instances to the zoo
zoo.add_animal(zebra_instance)
zoo.add_animal(lion_instance)
zoo.add_animal(eagle_instance)

# Display the animals in the zoo
zoo.display_animals()

# Convert the zoo to JSON
json_string = convert_to_json(zoo)
print(json_string)
```
This code defines a `Zoo` class that has methods for registering new types of animals, creating instances of those animals, adding and removing animals from the zoo, and displaying the animals in the zoo. It also includes a `convert_to_json()` method that converts the zoo object to JSON format.

The code also defines several animal classes, including `Mammal` and `Bird`, which are registered with unique IDs using the `register_animal()` method. Instances of these animals are created using the `create_animal()` method, and then added to the zoo using the `add_animal()` method.

Finally, the code demonstrates how to convert the zoo object to JSON format using the `convert_to_json()` method, which returns a JSON string representation of the zoo.']",1,[0],[],False,1,0,0,"[{""block_id"": 1, ""language"": ""unknown"", ""error"": ""Unsupported language: unknown""}]"

