0,"Design a Python program featuring a class hierarchy for geometric shapes: Circle, Rectangle, and Triangle. Implement methods to calculate properties like area and perimeter for each shape. Include a ShapeFactory class for registering new shape subclasses and instantiating them with parameters. Write a function to convert the collection of shapes into a JSON string representation.",680,,"[""```
class Shape:
    def __init__(self, x=0, y=0):
        self.x = x
        self.y = y

    def calculate_area(self):
        raise NotImplementedError()

    def calculate_perimeter(self):
        raise NotImplementedError()

class Circle(Shape):
    def __init__(self, radius=0, x=0, y=0):
        super().__init__(x, y)
        self.radius = radius

    def calculate_area(self):
        return math.pi * (self.radius ** 2)

    def calculate_perimeter(self):
        return 2 * math.pi * self.radius

class Rectangle(Shape):
    def __init__(self, width=0, height=0, x=0, y=0):
        super().__init__(x, y)
        self.width = width
        self.height = height

    def calculate_area(self):
        return self.width * self.height

    def calculate_perimeter(self):
        return 2 * (self.width + self.height)

class Triangle(Shape):
    def __init__(self, side1=0, side2=0, side3=0, x=0, y=0):
        super().__init__(x, y)
        self.side1 = side1
        self.side2 = side2
        self.side3 = side3

    def calculate_area(self):
        return (self.side1 + self.side2 + self.side3) / 2

class ShapeFactory:
    _shape_classes = {
        'Circle': Circle,
        'Rectangle': Rectangle,
        'Triangle': Triangle
    }

    @staticmethod
    def register_shape(name, shape_class):
        if name in ShapeFactory._shape_classes:
            raise ValueError('Shape already registered')
        ShapeFactory._shape_classes[name] = shape_class

    @staticmethod
    def create_shape(name, **kwargs):
        if name not in ShapeFactory._shape_classes:
            raise ValueError('Unknown shape type')
        return ShapeFactory._shape_classes[name](**kwargs)

def shapes_to_json(shapes):
    json_data = []
    for shape in shapes:
        json_data.append({
            'type': shape.__class__.__name__,
            'x': shape.x,
            'y': shape.y,
            'properties': {
                'area': shape.calculate_area(),
                'perimeter': shape.calculate_perimeter()
            }
        })
    return json.dumps(json_data)
```
