            if char not in node.children:
                node.children[char] = TrieNode()
            node = node.children[char]
        node.value = key

    def search(self, key):
        node = self
        for char in key:
            if char not in node.children:
                return None
            node = node.children[char]
        return node.value

    def delete(self, key):
        node = self
        for char in key[:-1]:
            if char not in node.children:
                return False
            node = node.children[char]
        if key[-1] not in node.children:
            return False
        del node.children[key[-1]]
        while len(node.children) == 0 and node.value is None:
            parent = node.parent
            del parent.children[node.value]
            node = parent
        return True

class Trie:
    def __init__(self):
        self.root = TrieNode()

    def insert(self, key):
        self.root.insert(key)

    def search(self, key):
        return self.root.search(key)

    def delete(self, key):
        return self.root.delete(key)
