class HashingAPI:
    def __init__(self):
        self.trie = Trie()
        self.hash_funcs = {
            ""sha256"": lambda text: sha256(text.encode(""utf-8"")).hexdigest(),
            ""aes"": lambda key, plaintext: b64encode(key + plaintext).decode(""utf-8"")
        }

    def hash_file(self, file_path):
        with open(file_path, ""rb"") as f:
            data = f.read()
        return self.hash(data)

    def hash(self, text):
        for func in self.hash_funcs.values():
            text = func(text)
        return text

    def get_hash(self, hash_func, plaintext):
        if hash_func not in self.hash_funcs:
            return None
        return self.hash_funcs[hash_func](plaintext)

    def get_info(self, hash_func, plaintext):
        if hash_func not in self.hash_funcs:
            return {}
        hashed = self.hash_funcs[hash_func](plaintext)
        return {
            ""hash"": hashed,
            ""bits_per_sample"": len(hashed) * 4
        }

    def get_stats(self, hash_func, plaintext):
        if hash_func not in self.hash_funcs:
            return {}
        info = self.get_info(hash_func, plaintext)
        bits_per_sample = info[""bits_per_sample""]
        return {
            ""samples"": len(plaintext),
            ""bits"": bits_per_sample * len(plaintext)
        }

    def update_trie(self, hash_func):
        if hash_func not in self.hash_funcs:
            return False
        self.trie.insert(hash_func)
        return True

    def delete_from_trie(self, hash_func):
        if hash_func not in self.hash_funcs:
            return False
        self.trie.delete(hash_func)
        return True

    def get_trie(self):
        return self.trie
