import os

def count_files_in_directory(input_dir, output_file=None):
    total_files = 0

    for root, _, files in os.walk(input_dir):
        total_files += len(files)

    if output_file:
        with open(output_file, 'w') as f:
            f.write(f""Total files: {total_files}"")
    else:
        print(f""Total files: {total_files}"")

def main():
    parser = argparse.ArgumentParser(description=""Count files in a directory and its subdirectories."")

    parser.add_argument('-d', '--directory', type=str, required=True, help=""Input directory path."")

    parser.add_argument('-o', '--output', type=str, default=None, help=""Output file path to store the result."")

    args = parser.parse_args()

    try:
        count_files_in_directory(args.directory, args.output)

        if args.output:
            with open(args.output, 'a') as f:
                f.write(""\nProcessing complete."")

    except Exception as e:
        print(f""An error occurred: {e}"")

if __name__ == ""__main__"":
    main()']",0,[0],[],True,0,0,0,

