def get_unique_apps(app_list):
    # Validate input list of apps
    if not app_list:
        raise ValueError(""Empty list of apps provided"")
    for app in app_list:
        if not isinstance(app, str):
            raise TypeError(""Invalid type for app name. Expected string."")

    # Create a new list with unique app names and sort it alphabetically
    unique_apps = []
    for app in app_list:
        if app not in unique_apps:
            unique_apps.append(app)
    unique_apps.sort()

    return unique_apps
