class TicketType:
    def __init__(self, name, price):
        self.name = name
        self.price = price

class Ticket:
    def __init__(self, ticket_type, seat_number, showtime):
        self.ticket_type = ticket_type
        self.seat_number = seat_number
        self.showtime = showtime
        self.status = 'available'

    def update_status(self, new_status):
        if new_status not in ['reserved', 'purchased']:
            raise ValueError(""Invalid status update"")
        self.status = new_status

class RegularTicket(Ticket):
    def __init__(self, seat_number, showtime):
        super().__init__(TicketType('regular', 10), seat_number, showtime)

class VIPTicket(Ticket):
    def __init__(self, seat_number, showtime):
        super().__init__(TicketType('VIP', 20), seat_number, showtime)

class StudentTicket(Ticket):
    def __init__(self, seat_number, showtime):
        super().__init__(TicketType('student', 5), seat_number, showtime)

class TicketingSystem:
    def __init__(self):
        self.tickets_sold = {}

    def add_ticket(self, ticket_type_name, seat_number=None):
        if seat_number is None:
            raise ValueError(""Seat number must be specified"")
        if ticket_type_name not in ['regular', 'VIP', 'student']:
            raise ValueError(""Invalid ticket type name"")
        if seat_number in self.tickets_sold:
            raise ValueError(""Seat number is already taken"")
        self.tickets_sold[seat_number] = Ticket(ticket_type_name, seat_number, showtime)
```
