class Tree:
    def __init__(self, tree_id, species, height):
        self.tree_id = tree_id
        self.species = species
        self.height = height

    def __repr__(self):
        return f""Tree(tree_id={self.tree_id}, species={self.species}, height={self.height})""

class Forest:
    def __init__(self, trees=[]):
        self.trees = trees

    @staticmethod
    def register_factory(tree_type):
        Forest.registered_factories[tree_type] = tree_type

    @staticmethod
    def generate_new_tree(tree_type, tree_id, species, height):
        if tree_type in Forest.registered_factories:
            return Forest.registered_factories[tree_type](tree_id, species, height)
        else:
            raise ValueError(""Tree type is not registered"")

    def add_tree(self, tree):
        self.trees.append(tree)

    def convert_to_json(self):
        return json.dumps([tree.__dict__ for tree in self.trees], indent=4)
```
