```
import os
import sys
import shutil
import cryptography
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.backends import default_backend

def operation_selector(file_path, command):
    if command == ""encrypt"":
        return encrypt_file(file_path)
    elif command == ""hash"":
        return hash_file(file_path)
    else:
        raise ValueError(""Invalid command"")

def encrypt_file(file_path):
    with open(file_path, ""rb"") as f:
        data = f.read()

    cipher = cryptography.hazmat.primitives.ciphers.Cipher(
        algorithm=cryptography.hazmat.primitives.ciphers.AES(b""my_secret_key""),
        mode=cryptography.hazmat.primitives.ciphers.Mode.ECB,
        backend=default_backend()
    )

    encrypted = cipher.encryptor().update(data) + cipher.encryptor().finalize()
    with open(""encrypted_"" + file_path, ""wb"") as f:
        f.write(encrypted)

def hash_file(file_path):
    hash = hashes.Hash(hashes.SHA256(), backend=default_backend())
    with open(file_path, ""rb"") as f:
        for chunk in iter(lambda: f.read(4096), b""""):
            hash.update(chunk)

    return hash.finalize().hexdigest()
```
