class Tree:
    def __init__(self, treeID, species, height):
        self.treeID = treeID
        self.species = species
        self.height = height

class Forest:
    def __init__(self):
        self.trees = {}

    def register_factory(self, tree_id, factory_func):
        self.trees[tree_id] = factory_func

    def generate_tree(self, tree_id):
        if tree_id in self.trees:
            return self.trees[tree_id]()
        else:
            raise ValueError(""Unknown tree ID"")

    def to_json(self):
        return json.dumps([t.to_dict() for t in self.trees.values()])
```
