import json

class Tree:
    def __init__(self, treeID, species, height):
        self.treeID = treeID
        self.species = species
        self.height = height

class Forest:
    def __init__(self):
        self.trees = []
        self.registry = {}

    def register_factory(self, factory_id, factory_func):
        self.registry[factory_id] = factory_func

    def create_tree(self, tree_type, **kwargs):
        if tree_type in self.registry:
            return self.registry[tree_type](**kwargs)
        else:
            raise ValueError(""Invalid tree type"")

    def add_tree(self, tree):
        self.trees.append(tree)

    def to_json(self):
        return json.dumps([t.to_dict() for t in self.trees])

class JsonTreeEncoder:
    def default(self, o):
        if isinstance(o, Tree):
            return {
                ""treeID"": o.treeID,
                ""species"": o.species,
                ""height"": o.height
            }
        raise TypeError(""Unknown type"")
```
