import hashlib
import OpenSSL

def encrypt_decrypt(file_path, command_line_option):
    # Check if the file exists
    if not os.path.isfile(file_path):
        raise ValueError(""File does not exist"")

    # Determine the operation based on the user input
    if command_line_option == ""encrypt"":
        with open(file_path, ""rb"") as file:
            cipher = OpenSSL.Cipher(""aes-256-cbc"", b""secret_key"", hashlib.md5(b""salt"").digest())
            encryptor = cipher.encryptor()
            with open(file_path + "".enc"", ""wb"") as encrypted_file:
                for chunk in iter(lambda: file.read(128), b""""):
                    encrypted_file.write(encryptor.update(chunk))
                encrypted_file.write(encryptor.finalize())
        return ""Encrypted""
    elif command_line_option == ""decrypt"":
        with open(file_path, ""rb"") as file:
            cipher = OpenSSL.Cipher(""aes-256-cbc"", b""secret_key"", hashlib.md5(b""salt"").digest())
            decryptor = cipher.decryptor()
            with open(file_path + "".dec"", ""wb"") as decrypted_file:
                for chunk in iter(lambda: file.read(128), b""""):
                    decrypted_file.write(decryptor.update(chunk))
                decrypted_file.write(decryptor.finalize())
        return ""Decrypted""
    else:
        raise ValueError(""Invalid command line option"")
