import os
import sys

def main():
    # Parse command line arguments
    args = sys.argv[1:]
    if not args:
        print(""Usage: python script.py [-d directory] [-o output_file]"")
        return

    # Process --help flag
    help_flag = False
    for arg in args:
        if arg == ""--help"":
            help_flag = True
            break

    # Set default values for input and output directories
    input_dir = "".""
    output_file = None

    # Process -d flag
    for arg in args:
        if arg.startswith(""-d""):
            input_dir = arg[2:]

    # Process -o flag
    for arg in args:
        if arg.startswith(""-o""):
            output_file = arg[2:]

    # Recursively enumerate files in input directory and subdirectories
    file_count = 0
    for root, dirs, files in os.walk(input_dir):
        file_count += len(files)

    # Output the total number of files found
    if output_file:
        with open(output_file, ""w"") as f:
            f.write(str(file_count))
    else:
        print(file_count)

if __name__ == ""__main__"":
    main()
