1,"Create a function to simulate weather conditions over a given period. The function should generate random precipitation amounts, temperature fluctuations, and wind speeds for each day within the specified timeframe. Additionally, include an option to introduce a specific weather pattern such as a heatwave or cold snap that affects the temperature for multiple consecutive days. Implement error handling for invalid input parameters and ensure the generated data is within realistic bounds for the chosen geographical location. Finally, provide a main function that demonstrates usage of this simulation function by generating a week's worth of weather data for a specific region, displaying it in a readable format.",680,,"['```
import random

def simulate_weather(start_date, end_date, location):
    # Generate random precipitation amounts
    precipitation = {}
    for day in range(start_date, end_date + 1):
        precipitation[day] = random.uniform(0, 1) * 24

    # Generate temperature fluctuations
    temperature = {}
    for day in range(start_date, end_date + 1):
        if day % 7 == 0:  # Heatwave pattern
            temperature[day] = random.uniform(25, 35)
        else:
            temperature[day] = random.uniform(15, 25)

    # Generate wind speeds
    wind_speeds = {}
    for day in range(start_date, end_date + 1):
        wind_speeds[day] = random.uniform(0, 20)

    # Add specific weather pattern (heatwave or cold snap)
    if location == ""New York"":
        heatwave = False
        for day in range(start_date, end_date + 1):
            if not heatwave:
                temperature[day] = random.uniform(25, 35)
            else:
                temperature[day] = random.uniform(30, 40)

    return {""precipitation"": precipitation, ""temperature"": temperature, ""wind_speeds"": wind_speeds}
