import hashlib
from collections import defaultdict

class HashingHelper:
    def __init__(self):
        self.cache = defaultdict(list)
        self.version = ""1.0""

    def generate_hash(self, data, use_hex=False):
        if isinstance(data, str):
            data = data.encode()
        hash = hashlib.md5(data).hexdigest() if use_hex else hashlib.md5(data).digest()
        return hash

    def update_hash(self, data, current_hash, use_hex=False):
        new_hash = self.generate_hash(data, use_hex)
        if new_hash != current_hash:
            raise ValueError(""Hash does not match the expected value"")
        return True

    def get_version(self):
        return self.version

class TreeNode:
    def __init__(self, data):
        self.data = data
        self.left = None
        self.right = None

    def insert(self, key, value):
        if key < self.data:
            if self.left is None:
                self.left = TreeNode(key)
            else:
                self.left.insert(key, value)
        elif key > self.data:
            if self.right is None:
                self.right = TreeNode(key)
            else:
                self.right.insert(key, value)
        else:
            self.data[key] = value

    def search(self, key):
        if key < self.data:
            return self.left.search(key) if self.left is not None else None
        elif key > self.data:
            return self.right.search(key) if self.right is not None else None
        else:
            return self.data[key]

    def delete(self, key):
        if key < self.data:
            if self.left is not None:
                self.left.delete(key)
        elif key > self.data:
            if self.right is not None:
                self.right.delete(key)
        else:
            del self.data[key]

class BinarySearchTree:
    def __init__(self, data):
        self.root = TreeNode(data)

    def insert(self, key, value):
        return self.root.insert(key, value)

    def search(self, key):
        return self.root.search(key)

    def delete(self, key):
        return self.root.delete(key)

class CachingSystem:
    def __init__(self):
        self.cache = defaultdict(list)

    def add_to_cache(self, data, use_hex=False):
        hash = HashingHelper().generate_hash(data, use_hex)
        self.cache[hash].append(data)
        return hash

    def get_from_cache(self, hash):
        if hash in self.cache:
            return self.cache[hash]
        else:
            return None

