    def append(self, node):
        if not self.head:
            self.head = node
            node.prev = None
            node.next = None
            return

        current_node = self.head
        while current_node.next:
            current_node = current_node.next

        current_node.next = node
        node.prev = current_node
        node.next = None

    def remove(self, node):
        if not (node.prev or node.next):
            return

