class AttackManager:
    def __init__(self):
        self.cache = {} # Dictionary to store the result of processed trees based on their structure and a unique identifier

    def compare_trees(self, tree1, tree2):
        """"""Compares two trees for equality and returns True if they are equal, False otherwise.""""""
        if not (tree1.head and tree2.head):
            return False
        current_node1 = tree1.head
        current_node2 = tree2.head
        while current_node1 and current_node2:
            if current_node1.data != current_node2.data:
                return False
            current_node1 = current_node1.next
            current_node2 = current_node2.next
        return not (current_node1 or current_node2)

    def generate_attack_tree(self, attack_nodes, cooldowns, descriptions):
        """"""Creates an attack tree from the given inputs.""""""
        # Check if the input parameters are valid
        if len(attack_nodes) != len(cooldowns) or len(attack_nodes) != len(descriptions):
            raise ValueError(""Invalid input parameters"")
        # Create a new tree structure with the given attack nodes, cooldowns and descriptions
        tree = TreeNode(""Root"")
        for i in range(len(attack_nodes)):
            node = AttackNode(i+1, cooldowns[i], descriptions[i])
            tree.append(node)
        # Return the new tree structure
        return tree

    def select_attack_strategy(self, tree):
        """"""Selects an optimal strategy based on the given criteria.""""""
        # Calculate the total cooldown time for all attacks in the tree
        total_cooldown = 0
        current_node = tree.head
        while current_node:
            total_cooldown += current_node.data.cooldown
            current_node = current_node.next
        # Calculate the combined attack power for all attacks in the tree
        combined_attack_power = 0
        current_node = tree.head
        while current_node:
            combined_attack_power += current_node.data.number * current_node.data.cooldown
            current_node = current_node.next
        # Select the optimal strategy based on the given criteria
        if total_cooldown < 100 or combined_attack_power > 200:
            return ""Optimal strategy 1""
        elif total_cooldown >= 100 and combined_attack_power <= 200:
            return ""Optimal strategy 2""
        else:
            raise ValueError(""Invalid input parameters"")

    def simulate_attacks(self, tree, strategy):
        """"""Simulates attacks on the given tree structure using the selected strategy.""""""
        # Check if the input parameters are valid
        if not (tree.head and strategy):
            raise ValueError(""Invalid input parameters"")
        # Initialize a list to store the results of each attack round
        results = []
        # Simulate attacks on the tree structure using the selected strategy
        for i in range(10): # Number of rounds to simulate attacks
            current_node = tree.head
            while current_node:
                if current_node.data.cooldown == 0:
                    results.append((current_node.data.number, ""Attack success""))
                    current_node.data.cooldown = strategy.cooldown
                else:
                    results.append((current_node.data.number, ""Attack failure""))
                current_node = current_node.next
        # Return the list of simulation results
        return results

    def log(self, message):
        """"""Logs the given message to a file.""""""
        # Open a file to store the logs
        with open(""attack_manager_logs.txt"", ""a"") as f:
            f.write(f""{message}\n"")
