Here is the modified Python script that incorporates image processing functionalities based on the provided fields:
```python
import argparse
import os
from PIL import Image

def main():
    parser = argparse.ArgumentParser(description=""Directory listing tool with file count"")
    parser.add_argument('-d', '--directory', type=str, required=True,
                        help='Input directory for file listing')
    parser.add_argument('-o', '--output', type=str, default='output.txt',
                        help='Output file name')
    parser.add_argument('--help', action='store_true',
                        help='Show this help message and exit')

    args = parser.parse_args()

    if args.help:
        parser.print_help()
        return

    # Directory listing and count function
    def list_directory(directory):
        total_files = 0
        for root, _, files in os.walk(directory):
            total_files += len(files)
            print(f""Files in {root}: {len(files)}"")

        return total_files

    # Outputting total files
    total_count = list_directory(args.directory)

    # Writing output to a file
    with open(args.output, 'w') as f:
        f.write(f'Total files: {total_count}')

    # Extracting image information
    def extract_image_info(filename):
        try:
            with Image.open(filename) as im:
                width, height = im.size
                mode = im.mode
                channels = im.channels
                exif_data = im._getexif()
                if exif_data is not None:
                    exif_dict = {
                        ExifTags.TAGS[k]: v for k, v in exif_data.items() if k in ExifTags.TAGS
                    }
                    if 'ApertureValue' in exif_dict and 'ExposureTime' in exif_dict:
                        aperture = float(exif_dict['ApertureValue']) / 100
                        shutter = float(exif_dict['ExposureTime'])
                        fnumber = aperture * shutter
                        return {'width': width, 'height': height, 'mode': mode, 'channels': channels, 'fnumber': fnumber}
                else:
                    return {'width': width, 'height': height, 'mode': mode, 'channels': channels}
        except Exception as e:
            print(f""Error extracting image information from {filename}: {e}"")
            return {}

    # Processing images in the directory
    if total_count > 0:
        for root, dirs, files in os.walk(args.directory):
            for file in files:
                filename = os.path.join(root, file)
                if filename.endswith('.jpg') or filename.endswith('.jpeg'):
                    info = extract_image_info(filename)
                    if info:
                        print(f""Image {filename}:"")
                        for k, v in info.items():
                            print(f""\t{k}: {v}"")
                else:
                    print(f""Ignoring file {filename} - not an image."")

if __name__ == ""__main__"":
   main()
```
This script now extracts information from images using the `PIL` library and stores it in a dictionary with keys `width`, `height`, `mode`, `channels`, and optionally `fnumber`. The script also outputs information about the images found in the directory, including their dimensions, file format, mode, channels, and f-number (if available).']",2,[0],[],True,0,0,0,

